// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.iterator;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.NoSuchElementException;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.common.iteration.AbstractCloseableIteration;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.HashJoinBindingContract;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * Input lifecycle of {@link HashJoinIteration}: opening the two inputs must never leak one of them when opening the
 * other fails, because the iteration object that would otherwise close them is never constructed.
 */
class HashJoinIterationLifecycleTest {

	private static final QueryEvaluationContext CONTEXT = new QueryEvaluationContext.Minimal(null);
	private static final HashJoinBindingContract CONTRACT = HashJoinBindingContract.legacy(new String[] { "x" });

	@Test
	void hashJoinClosesLeftWhenRightEvaluationFails() {
		AtomicBoolean leftClosed = new AtomicBoolean();
		QueryEvaluationStep left = bindings -> emptyIteration(() -> leftClosed.set(true));
		QueryEvaluationStep right = bindings -> {
			throw new QueryEvaluationException("right evaluation failed");
		};

		assertThatThrownBy(() -> new HashJoinIteration(left, right, EmptyBindingSet.getInstance(), false, CONTRACT,
				CONTEXT, HashJoinIteration.BuildSide.UNKNOWN, null))
						.isInstanceOf(QueryEvaluationException.class)
						.hasMessage("right evaluation failed");
		assertThat(leftClosed).as("left input must be closed when opening the right input fails").isTrue();
	}

	@Test
	void leftJoinConstructorClosesLeftWhenRightEvaluationFails() {
		AtomicBoolean leftClosed = new AtomicBoolean();
		QueryEvaluationStep left = bindings -> emptyIteration(() -> leftClosed.set(true));
		QueryEvaluationStep right = bindings -> {
			throw new QueryEvaluationException("right evaluation failed");
		};

		assertThatThrownBy(() -> new HashJoinIteration(left, right, EmptyBindingSet.getInstance(), true, CONTRACT,
				CONTEXT, HashJoinIteration.BuildSide.RIGHT, null))
						.isInstanceOf(QueryEvaluationException.class);
		assertThat(leftClosed).isTrue();
	}

	@Test
	void leftCloseFailureDuringCleanupIsAttachedAsSuppressed() {
		QueryEvaluationStep left = bindings -> emptyIteration(() -> {
			throw new IllegalStateException("left close failed");
		});
		QueryEvaluationStep right = bindings -> {
			throw new QueryEvaluationException("right evaluation failed");
		};

		assertThatThrownBy(() -> new HashJoinIteration(left, right, EmptyBindingSet.getInstance(), false, CONTRACT,
				CONTEXT, HashJoinIteration.BuildSide.UNKNOWN, null))
						.isInstanceOf(QueryEvaluationException.class)
						.hasMessage("right evaluation failed")
						.satisfies(failure -> {
							assertThat(failure.getSuppressed()).hasSize(1);
							assertThat(failure.getSuppressed()[0])
									.isInstanceOf(IllegalStateException.class)
									.hasMessage("left close failed");
						});
	}

	@Test
	void leftOpenFailureDoesNotOpenRight() {
		AtomicInteger rightOpens = new AtomicInteger();
		QueryEvaluationStep left = bindings -> {
			throw new QueryEvaluationException("left evaluation failed");
		};
		QueryEvaluationStep right = bindings -> {
			rightOpens.incrementAndGet();
			return emptyIteration(() -> {
			});
		};

		assertThatThrownBy(() -> new HashJoinIteration(left, right, EmptyBindingSet.getInstance(), false, CONTRACT,
				CONTEXT, HashJoinIteration.BuildSide.UNKNOWN, null))
						.isInstanceOf(QueryEvaluationException.class)
						.hasMessage("left evaluation failed");
		assertThat(rightOpens).hasValue(0);
	}

	@Test
	void successfulConstructionKeepsBothInputsOpenUntilClose() {
		AtomicBoolean leftClosed = new AtomicBoolean();
		AtomicBoolean rightClosed = new AtomicBoolean();
		QueryEvaluationStep left = bindings -> emptyIteration(() -> leftClosed.set(true));
		QueryEvaluationStep right = bindings -> emptyIteration(() -> rightClosed.set(true));

		HashJoinIteration iteration = new HashJoinIteration(left, right, EmptyBindingSet.getInstance(), false,
				CONTRACT, CONTEXT, HashJoinIteration.BuildSide.UNKNOWN, null);
		assertThat(leftClosed).isFalse();
		assertThat(rightClosed).isFalse();
		iteration.close();
		assertThat(leftClosed).isTrue();
		assertThat(rightClosed).isTrue();
	}

	private static AbstractCloseableIteration<BindingSet> emptyIteration(Runnable onClose) {
		return new AbstractCloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return false;
			}

			@Override
			public BindingSet next() {
				throw new NoSuchElementException();
			}

			@Override
			protected void handleClose() {
				onClose.run();
			}
		};
	}
}
